mapper.select:
SELECT g.studentId, g.unread, g.lastTime, u.nickname AS studentName, u.username AS studentUsername, (SELECT m.content FROM psy_chat_message m WHERE m.student_id = g.studentId ORDER BY m.id DESC LIMIT 1) AS lastContent FROM ( SELECT c.student_id AS studentId, COUNT(*) AS unread, MAX(c.create_time) AS lastTime FROM psy_chat_message c WHERE c.sender_role = 'student' AND c.is_read = 0 GROUP BY c.student_id ) g LEFT JOIN sys_user u ON g.studentId = u.user_id WHERE 1 = 1
AND g.studentId IN ( SELECT p.user_id FROM psy_patient p WHERE p.user_id IS NOT NULL AND (p.teacher_id = #{teacherId} OR p.teacher_id IS NULL) )
ORDER BY g.lastTime DESC LIMIT #{limit}

SELECT f.id, f.user_id AS userId, f.record_id AS recordId, f.follow_date AS followDate, f.follow_type AS followType, f.status, u.nickname AS studentName, u.username AS studentUsername FROM psy_follow_up f LEFT JOIN sys_user u ON f.user_id = u.user_id WHERE f.status != '已完成' AND f.follow_date < CURDATE()
AND f.user_id IN ( SELECT p.user_id FROM psy_patient p WHERE p.user_id IS NOT NULL AND (p.teacher_id = #{teacherId} OR p.teacher_id IS NULL) )
ORDER BY f.follow_date ASC LIMIT #{limit}

SELECT tr.record_id AS recordId, tr.user_id AS userId, tr.level, tr.std_score AS stdScore, tr.create_time AS createTime, ps.scale_name AS scaleName, u.nickname AS studentName, u.username AS studentUsername FROM psy_test_record tr LEFT JOIN psy_scale ps ON tr.scale_id = ps.scale_id LEFT JOIN sys_user u ON tr.user_id = u.user_id WHERE (tr.doctor_conclusion IS NULL OR tr.doctor_conclusion = '') AND (tr.level LIKE '%中度%' OR tr.level LIKE '%重度%')
AND tr.user_id IN ( SELECT p.user_id FROM psy_patient p WHERE p.user_id IS NOT NULL AND (p.teacher_id = #{teacherId} OR p.teacher_id IS NULL) )
ORDER BY tr.create_time DESC LIMIT #{limit}

SELECT tr.record_id AS recordId, tr.user_id AS userId, tr.level, tr.std_score AS stdScore, tr.create_time AS createTime, ps.scale_name AS scaleName, u.nickname AS studentName, u.username AS studentUsername FROM psy_test_record tr LEFT JOIN psy_scale ps ON tr.scale_id = ps.scale_id LEFT JOIN sys_user u ON tr.user_id = u.user_id WHERE (tr.level LIKE '%中度%' OR tr.level LIKE '%重度%') AND tr.create_time >= #{weekStart}
AND tr.user_id IN ( SELECT p.user_id FROM psy_patient p WHERE p.user_id IS NOT NULL AND (p.teacher_id = #{teacherId} OR p.teacher_id IS NULL) )
ORDER BY tr.create_time DESC LIMIT #{limit}
